preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtweb-font-size로 바꿉니다. */
.rtweb {
  --rtweb-bg-fill: transparent;
  --rtweb-blur: none;
  --rtweb-bg-edge: none;
  --rtweb-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtweb-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtweb-font-size: 16.5px;
  --rtweb-line-height: 1.95;
  --rtweb-para-gap: 1.5em;
  --rtweb-measure: 38em;
  --rtweb-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtweb {
  --risu-font-family: var(--rtweb-font-body);
  --FontColorStandard: var(--rtweb-ink);
  --FontColorBold: var(--rtweb-ink);
  --FontColorItalic: var(--rtweb-muted);
  --FontColorItalicBold: var(--rtweb-muted);
  --FontColorQuote1: var(--rtweb-muted);
  --FontColorQuote2: var(--rtweb-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtweb-ink);
  font-family: var(--rtweb-font-body);
  font-size: var(--rtweb-font-size);
  line-height: var(--rtweb-line-height);
}
.rtweb, .rtweb *, .rtweb *::before, .rtweb *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtweb.rtweb { display: block; }
.rtweb__content {
  min-width: 0;
  color: var(--rtweb-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtweb__content .chattext {
  --tw-prose-code: var(--rtweb-ink);
  --tw-prose-pre-code: var(--rtweb-ink);
  --tw-prose-pre-bg: var(--rtweb-tint);
  max-width: none;
  color: var(--rtweb-ink);
  font-size: var(--rtweb-font-size) !important;
  line-height: var(--rtweb-line-height) !important;
}
.rtweb__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtweb-font-size);
  line-height: var(--rtweb-line-height);
}
.rtweb__content p { margin: 0 0 var(--rtweb-para-gap); }
.rtweb__content p:last-child { margin-bottom: 0; }
.rtweb__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtweb-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtweb-ink);
  font-family: var(--rtweb-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtweb__content h1 { font-size: calc(var(--rtweb-font-size) * 1.6); }
.rtweb__content h2 { font-size: calc(var(--rtweb-font-size) * 1.35); }
.rtweb__content h3 { font-size: calc(var(--rtweb-font-size) * 1.15); }
.rtweb__content :is(h4, h5, h6) { font-size: var(--rtweb-font-size); }
.rtweb__content strong { font-weight: 700; }
.rtweb__content em { color: var(--rtweb-muted); }
.rtweb__content mark[risu-mark="quote1"],
.rtweb__content mark[risu-mark="blockquote1"] { color: var(--rtweb-muted); background: transparent; }
.rtweb__content mark[risu-mark="quote2"],
.rtweb__content mark[risu-mark="blockquote2"] {
  color: var(--rtweb-dialog);
  font-weight: var(--rtweb-dialog-weight);
  background: transparent;
}
.rtweb__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtweb-line);
  color: var(--rtweb-muted);
}
.rtweb__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtweb__content li { margin: .25em 0; color: var(--rtweb-ink); }
.rtweb__content li::marker { color: var(--rtweb-muted); }
.rtweb__content a { color: var(--rtweb-accent); text-decoration: underline; }
.rtweb__content hr { border: 0; border-top: 1px solid var(--rtweb-line); margin: 1.5em 0; }
.rtweb__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtweb-ink);
  background: var(--rtweb-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtweb-font-size) * .88);
}
.rtweb__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtweb-ink);
  background: var(--rtweb-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtweb-font-size) * .88);
  line-height: 1.5;
}
.rtweb__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtweb__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtweb__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtweb-ink);
  border-bottom: 1px solid var(--rtweb-line);
  text-align: left;
  vertical-align: top;
}
.rtweb__content th { font-weight: 700; }
.rtweb__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtweb__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtweb-ink) !important;
  background: var(--rtweb-edit-bg) !important;
  border: 1px solid var(--rtweb-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtweb-font-size) !important;
  line-height: var(--rtweb-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtweb__footer {
  --risu-theme-textcolor2: var(--rtweb-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtweb__info, .rtweb__actions { min-width: 0; max-width: 100%; }
.rtweb__info > div, .rtweb__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtweb__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtweb__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtweb__footer button:hover { background: var(--rtweb-tint); }
.rtweb :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtweb-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtweb__portrait { overflow: hidden; background: var(--rtweb-tint); }
.rtweb__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtweb__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtweb-bg-fill);
  -webkit-backdrop-filter: var(--rtweb-blur);
  backdrop-filter: var(--rtweb-blur);
  box-shadow: var(--rtweb-bg-edge);
}

/* 구조: 웹소설 */

.rtweb { background: var(--rtweb-paper); padding: 0 clamp(1.1rem, 4vw, 2.5rem); }
.rtweb__page { max-width: var(--rtweb-measure); margin: 0 auto; padding: 1.6rem 0 1.1rem; }
.rtweb__head { display: flex; align-items: center; gap: .7rem; margin-bottom: 1.1rem; color: var(--rtweb-accent); font-size: .82em; font-weight: 700; }
.rtweb__head::after { content: ""; flex: 1 1 auto; height: 1px; background: var(--rtweb-line); }
.rtweb--user .rtweb__page { display: flex; flex-direction: column; align-items: flex-end; padding: .5rem 0 .9rem; }
.rtweb--user .rtweb__head { display: none; }
.rtweb--user .rtweb__content {
  max-width: min(85%, 30em);
  padding: .55em 1em;
  border: 1px solid var(--rtweb-line);
  border-left: 3px solid var(--rtweb-accent);
  border-radius: .4em;
  background: var(--rtweb-tint);
}
.rtweb--user .rtweb__content .chattext,
.rtweb--user .rtweb__content :is(p, li) { font-size: calc(var(--rtweb-font-size) * .92) !important; line-height: 1.6 !important; }
.rtweb--user .rtweb__content p { margin-bottom: .4em; }
.rtweb__footer { margin-top: .6rem; }

.rtweb__footer { opacity: 0; transition: opacity .2s ease; }
.rtweb:hover .rtweb__footer, .rtweb:focus-within .rtweb__footer { opacity: 1; }
@media (hover: none) { .rtweb__footer { opacity: .55; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (흰색) ── */
.rtweb {
  --rtweb-paper: #fbfaf8;
  --rtweb-ink: #262422;
  --rtweb-muted: #7a7570;
  --rtweb-accent: #7a6a58;
  --rtweb-dialog: #111111;
  --rtweb-line: #e6e2dc;
  --rtweb-tint: #f1ede7;
  --rtweb-edit-bg: #ffffff;
}
